# Generated by build.py from recipe.yml for recipe s3-sign-a-run-of-s3-requests. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'store/reports', 'readonly/reports' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'q3.csv'), "region,total`nnorth,1200`n")
[IO.File]::WriteAllText((Join-Path $PWD 'store/reports/2026-q2.csv'), "region,total`nnorth,1100`n")
[IO.File]::WriteAllText((Join-Path $PWD 'readonly/reports/2026-q2.csv'), "region,total`nnorth,1100`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1,DNS:*.s3.us-east-1.amazonaws.com"'
$server0 = Start-Process surl -ArgumentList '--directory', 'store', '--cert', 'server.pem', '--key', 'server.key', '--user', 'AKIAIOSFODNN7EXAMPLE:s3cret', '--allow-uploads', '--list-directories', 's3://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --cacert server.pem --connect-to ::127.0.0.1:8080 -u AKIAIOSFODNN7EXAMPLE:s3cret -T q3.csv s3://reports/2026-q3.csv s3://reports/ } finally { Stop-Process $server0 }
